  const selection=runUserSelectionGeneration;
  const current=()=>entry.identity===token && entry.project===$("project-select").value;
  entry.state="sending";
  entry.message=`正在确认提交。已冻结目标与 ${entry.body.resource_refs.length} 份材料；请勿另建重复任务。`;
