async function columnPatchGraphSeal(p,c){const g=p.graph,a=c.anchor.graph,b=p.definition.column_binding;if(g.schema_version!==a.schema_version||g.authorization_revision!==a.authorization_revision||await deliveryDigest({baseline_context:a.context_fingerprint,column_binding:b})!==g.context_fingerprint)return false;const affected=new Set(p.modified_objects.map(n=>n.id));for(const node of g.nodes){const original=a.nodes.find(n=>n.id===node.id),definition=JSON.parse(JSON.stringify(original.definition));if(node.id===b.node_id)definition.column_binding=b;if(node.kind==="MANIFEST")definition.preview_column_binding=b;const {content_fingerprint,...body}=node,expected={...original,definition,revision:original.revision+(affected.has(node.id)?1:0)};delete expected.content_fingerprint;if(!deliverySame(body,expected))return false;}const sealed=new Map();while(sealed.size<g.nodes.length){const ready=g.nodes.filter(n=>!sealed.has(n.id)&&g.edges.filter(e=>e.downstream===n.id).every(e=>sealed.has(e.upstream)));if(!ready.length)return false;for(const node of ready){const incoming=[];for(const edge of g.edges.filter(e=>e.downstream===node.id)){const upstream=sealed.get(edge.upstream),value={...edge,revision:upstream.revision,content_fingerprint:upstream.content_fingerprint};incoming.push({value,hash:await deliveryDigest(value)});}incoming.sort((x,y)=>x.hash<y.hash?-1:x.hash>y.hash?1:0);const {content_fingerprint,...body}=node;if(await deliveryDigest({...body,upstream_versions:incoming.map(x=>x.value)})!==content_fingerprint)return false;sealed.set(node.id,node);}}const r=p.plan,{plan_fingerprint,...plan}=r;if(await deliveryDigest(plan)!==plan_fingerprint||r.request_key!==p.request_key||r.graph_fingerprint!==a.graph_fingerprint||r.context_fingerprint!==a.context_fingerprint||r.project_id!==c.project||r.app_id!==c.id||r.patch_executed!==false||r.business_write_performed!==false||r.publishable!==false||!deliverySame(r.changed_nodes,[b.node_id])||!deliverySame(r.revalidation_nodes,a.nodes.m